def render(values, height=100, bar_width=20, gap=4):
    rects = "".join(
        f'<rect x="{i * bar_width}" y="0" width="{bar_width}" height="{v}"/>'
        for i, v in enumerate(values))
    width = len(values) * bar_width
    return f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}">{rects}</svg>'


def preview():
    return render([3, 7, 2, 9, 5])

