def render(points, width=100, height=20):
    pts = " ".join(f"{i},{p}" for i, p in enumerate(points))
    return (f'<svg xmlns="http://www.w3.org/2000/svg" width="{width}" height="{height}">'
            f'<polyline fill="none" points="{pts}"/></svg>')


def preview():
    return render([4, 6, 5, 9, 7, 12, 10])
